function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message, title) {
  const body = [];
  if (title) {
    body.push({
      type: "TextBlock",
      text: String(title).toUpperCase(),
      weight: "Bolder",
      size: "Large",
      wrap: true
    });
  }
  const msg = String(message ?? "N/D").trim();
  if (msg) {
    body.push({ type: "TextBlock", text: msg, wrap: true });
  }
  if (!body.length) {
    body.push({ type: "TextBlock", text: "N/D", wrap: true });
  }
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body
  };
}

// === Function – Build Teams payload (ALERTA) — versión multi-item (con filtro ALARM) ===
const P = $node["Set - Params"].json || {};

// 1) Trae todos los items del nodo anterior PERO filtra solo los que están en ALARM
const inItems = ($items() || [])
  .map(i => i.json)
  .filter(j => String(j.state || '').toUpperCase() === 'ALARM');  // <-- clave

// helpers numéricos
const num  = v => (v == null ? null : Number(v));
const fmt2 = v => (Number.isFinite(num(v)) ? num(v).toFixed(2) : String(v ?? "N/D"));
const pct  = v => (Number.isFinite(num(v)) ? `${num(v).toFixed(2)}%` : "N/D%");

const out = [];

for (const j of inItems) {
  const inst   = j.instance_name || "N/D";
  const unidad = j.unidad || "N/D";
  const usado  = pct(j.usado_pct);
  const thr    = (j.threshold != null) ? `${j.threshold}%` : "N/D%";

  // título principal
  const title = `${P.title_prefix || "ALERTA – Disco"} • ${inst} • ${unidad} • ${usado} (umbral ${thr})`.toUpperCase();

  // facts principales
  const facts = [
    { name: "Instancia",       value: inst },
    { name: "Unidad",          value: unidad },
    { name: "Tamaño (GB)",     value: fmt2(j.tamano_gb) },
    { name: "Disponible (GB)", value: fmt2(j.disponible_gb) },
    { name: "Usado %",         value: usado },
    { name: "Umbral",          value: thr },
    ...(j.estado_sp ? [{ name: "Estado SP", value: String(j.estado_sp) }] : []),
    {
      name: "Hora local",
      value: new Date(
        Date.now() + (Number(P.tz_offset_hours || 0) * 3600 * 1000)
      ).toISOString().replace("T"," ").substring(0,19)
    }
  ];

  // extras construidos en "Function – Build extras (storage)"
  const ex = j.extras_storage || {};
  const titleFiles = ex.titles?.files || `📦 Archivos de base de datos (detalle por archivo en la unidad ${unidad || 'actual'})`;
  const titleTopDb = ex.titles?.topdb || "🧩 Bases con mayor tamaño total (suma de archivos, todas las unidades)";
  const titleGrow  = ex.titles?.grow  || "⚙️ Autogrowth en 24 h (crecimientos detectados, MB)";

  const sections = [
    { markdown: true, text: "🔴 **ALERTA – Espacio en disco**" },
    { markdown: true, facts }
  ];

  // helper para listas
  const pushListSection = (title, lines) => {
    if (Array.isArray(lines) && lines.length) {
      sections.push({
        markdown: true,
        text: `**${title}**`,
        facts: lines.map(s => ({ name: "", value: s }))
      });
    }
  };

  // bloques extra
  pushListSection(titleFiles, ex.top_files);
  pushListSection(titleTopDb,  ex.top_db);
  pushListSection(titleGrow,   ex.autogrow);

  // botón opcional (Kibana u otro)
  const actions = [];
  if (P.emit_kibana_button && P.kibana_url) {
    actions.push({
      "@type": "OpenUri",
      "name": P.kibana_cta_text || "Abrir tablero (24h)",
      "targets": [{ "os": "default", "uri": P.kibana_url }]
    });
  }

  // tarjeta final (una por unidad)
  out.push({
    json: {
      "@type": "MessageCard",
      "@context": "https://schema.org/extensions",
      themeColor: "E81123",
      summary: title,
      title,
      sections,
      potentialAction: actions
    }
  });
}

// devuelve todas las tarjetas (una por unidad en ALARM)
return out.map(item => {
  const card = item.json;
  const title = String(card.title || '').toUpperCase();
  // cuerpo sin repetir el título (ya va como TextBlock grande/negrita)
  const lines = [];
  for (const sec of (card.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) {
        if (f.name) lines.push('- **' + f.name + ':** ' + f.value);
        else if (f.value) lines.push('- ' + f.value);
      }
    }
    lines.push('');
  }
  const message = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  return { json: { body: toAdaptiveCardBody(message, title) } };
});

