/* ===== Persistencia por unidad – disk.* (per-unidad en metric_name) [SQL 2008 R2] ===== */
SET NOCOUNT ON;
SET ARITHABORT ON;

DECLARE @now_utc DATETIME;
SET @now_utc = GETUTCDATE();

/* 1) Capturar los valores del item actual */
DECLARE @vals TABLE(
  instance_name nvarchar(200),
  unidad        nvarchar(50),
  tam_gb        float,
  disp_gb       float,
  usado_pct     float
);

INSERT INTO @vals(instance_name, unidad, tam_gb, disp_gb, usado_pct)
SELECT
  CAST(N'{{$json.instance_name}}' AS nvarchar(200)),
  CAST(N'{{$json.unidad}}'        AS nvarchar(50)),
  CAST(NULLIF(N'{{$json.tamano_gb}}',     N'') AS float),
  CAST(NULLIF(N'{{$json.disponible_gb}}', N'') AS float),
  CAST(NULLIF(N'{{$json.usado_pct}}',     N'') AS float);

/* 2) Upsert de la instancia */
IF NOT EXISTS (
  SELECT 1
  FROM OpsObservability.dbo.monitoring_instance mi WITH (NOLOCK)
  JOIN @vals v ON v.instance_name = mi.instance_name
)
BEGIN
  INSERT INTO OpsObservability.dbo.monitoring_instance(instance_name, environment, region)
  SELECT v.instance_name, 'prod', 'eastus2' FROM @vals v;
END

/* 3) instance_id + valores normalizados */
DECLARE @instance_id   int,
        @instance_name nvarchar(200),
        @unidad        nvarchar(50),
        @tam_gb        float,
        @disp_gb       float,
        @usado_value   float;

SELECT TOP 1
  @instance_name = v.instance_name,
  @unidad        = v.unidad,
  @tam_gb        = ISNULL(v.tam_gb,  0),
  @disp_gb       = ISNULL(v.disp_gb, 0),
  @usado_value   = ISNULL(v.usado_pct, 0)
FROM @vals v;

SELECT TOP 1
  @instance_id = mi.instance_id
FROM OpsObservability.dbo.monitoring_instance mi WITH (NOLOCK)
WHERE mi.instance_name = @instance_name;

/* 4) dim_json */
DECLARE @dim nvarchar(max);
SET @dim = N'{"unidad":"' + REPLACE(@unidad,'"','\"') +
          '","tamano_gb":'    + CONVERT(nvarchar(50), @tam_gb) +
          ',"disponible_gb":' + CONVERT(nvarchar(50), @disp_gb) + '}';

/* 5) Construir metric_name per-unidad (C|E|S). Quitamos ':' y dejamos mayúscula */
DECLARE @unidad_key nvarchar(10);
SET @unidad_key = UPPER(REPLACE(@unidad, ':', ''));  -- p.ej. 'C', 'E', 'S'

DECLARE @m_used  nvarchar(100) = N'disk.used_pct.'  + @unidad_key;
DECLARE @m_free  nvarchar(100) = N'disk.free_gb.'   + @unidad_key;
DECLARE @m_total nvarchar(100) = N'disk.total_gb.'  + @unidad_key;

/* 6) Idempotencia por (ts_utc, instance_id, metric_name per-unidad) */
DELETE FROM OpsObservability.dbo.monitoring_metric_timeseries
WHERE ts_utc      = @now_utc
  AND instance_id = @instance_id
  AND metric_name IN (@m_used, @m_free, @m_total);

/* 7) Inserts (uno por cada métrica per-unidad) */
INSERT INTO OpsObservability.dbo.monitoring_metric_timeseries
  (ts_utc, instance_id, metric_name,   metric_value, dim_json, run_id)
VALUES
  (@now_utc, @instance_id, @m_used,    @usado_value, @dim, NEWID());

INSERT INTO OpsObservability.dbo.monitoring_metric_timeseries
  (ts_utc, instance_id, metric_name,   metric_value, dim_json, run_id)
VALUES
  (@now_utc, @instance_id, @m_free,    @disp_gb,     @dim, NEWID());

INSERT INTO OpsObservability.dbo.monitoring_metric_timeseries
  (ts_utc, instance_id, metric_name,   metric_value, dim_json, run_id)
VALUES
  (@now_utc, @instance_id, @m_total,   @tam_gb,      @dim, NEWID());

/* 8) Salida */
SELECT @instance_name AS instance_name, @unidad AS unidad, @usado_value AS usado_pct, @now_utc AS ts_utc;

/* ===== Disco – lectura directa del SP ===== */
SET NOCOUNT ON;
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
DECLARE @sql nvarchar(200) = N'EXEC sqldb_database_maintenance..usp_MonitoreoUnidadesDisco';
EXEC (@sql);

