const P = $node["Set - Params"].json || {};
const rows = $items().map(i => i.json);   // <- clave: tomar TODOS los ítems del MSSQL

return rows.map(r => ({
  json: {
    instance_name: P.instance_name || "N/D",
    unidad: String(r.Unidad || r.unidad || "").trim(),
    tamano_gb: Number(r.Tamano_GB ?? r["Tamaño_GB"] ?? r.tamano_gb ?? 0),
    disponible_gb: Number(r.Disponible_GB ?? r.disponible_gb ?? 0),
    usado_pct: Number(r.Porcentaje_Usado ?? r.porcentaje_usado ?? 0),
    estado_sp: (r.Estado || r.estado || "").toString()
  }
}));

// ===== Function – Decidir estado (v5) =====
const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
const nowIso = new Date().toISOString();
const TH = Number($node['Set - Params'].json['threshold_disk_pct'] ?? 90);

// Normalizador robusto: "c", "C:", " C : " -> "C"
const normU = u => String(u || '').toUpperCase().replace(/\s+/g,'').replace(':','');

const actuales = ($items('Function – Expand filas') || []).map(i => i.json);

// lee últimos estados
const lastRows = ($items('MSSQL – “Last state por unidad”') || []).map(i => i.json);
const lastMap = {};                 // "C"|"D"|"E" -> { state, last_change_utc }
for (const r of lastRows) {
  const key = normU(r?.unidad);
  if (!key) continue;
  lastMap[key] = {
    state: String(r?.last_state || '').toUpperCase(), // 'ALARM'|'NORMAL'
    last_change_utc: r?.last_change_utc || null
  };
}

const out = [];
const seenToday = new Set();

for (const row of actuales) {
  const unidadRaw = row.unidad;
  const unidadKey = normU(unidadRaw);
  if (!unidadKey) continue;

  seenToday.add(unidadKey);

  const usado  = num(row.usado_pct);
  const tamGB  = num(row.tamano_gb);
  const dispGB = num(row.disponible_gb);

  const prev     = (lastMap[unidadKey]?.state) || 'UNKNOWN';
  const stateNow = (usado >= TH) ? 'ALARM' : 'NORMAL';

  let transition = 'NONE';
  if (prev !== 'ALARM' && stateNow === 'ALARM') transition = 'RAISE';
  else if (prev === 'ALARM' && stateNow === 'NORMAL') transition = 'RECOVER';
  else if (prev === 'ALARM' && stateNow === 'ALARM') transition = 'HOLD';

  const alarm_started_at = (transition === 'RECOVER') ? (lastMap[unidadKey]?.last_change_utc || null) : null;
  const alarm_duration_min = (transition === 'RECOVER' && alarm_started_at)
    ? Math.max(0, Math.round((new Date(nowIso) - new Date(alarm_started_at)) / 60000))
    : null;

  out.push({
    json: {
      instance_name: row.instance_name,
      unidad: unidadRaw,              // conserva “C:”, “S:”, etc. para las tarjetas
      tamano_gb: tamGB,
      disponible_gb: dispGB,
      usado_pct: usado,
      threshold: TH,
      estado_sp: row.estado_sp,
      state: stateNow,
      transition,
      last_change: nowIso,
      ts_utc: nowIso,
      alarm_started_at,
      alarm_duration_min
    }
  });
}

// Síntesis de RECOVERY si ayer estaba en ALARM y hoy no vino en el SP
for (const [unidadKey, info] of Object.entries(lastMap)) {
  if (info.state !== 'ALARM') continue;
  if (seenToday.has(unidadKey)) continue;

  const alarm_started_at = info.last_change_utc || null;
  const alarm_duration_min = alarm_started_at
    ? Math.max(0, Math.round((new Date(nowIso) - new Date(alarm_started_at)) / 60000))
    : null;

  out.push({
    json: {
      instance_name: $node['Set - Params'].json.instance_name || 'N/D',
      // mostramos como “C:” en UI, pero la clave se normalizó arriba
      unidad: `${unidadKey}:`,
      tamano_gb: null,
      disponible_gb: null,
      usado_pct: null,
      threshold: TH,
      estado_sp: 'RECUPERADA',
      state: 'NORMAL',
      transition: 'RECOVER',
      last_change: nowIso,
      ts_utc: nowIso,
      alarm_started_at,
      alarm_duration_min
    }
  });
}

return out;

function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Function – Build recovery payload (enriquecido) ===
const P = ($item(0).$node["Set - Params"]?.json) || {};
const j = $json;

const num  = v => (v == null ? null : Number(v));
const fmt2 = v => (Number.isFinite(num(v)) ? num(v).toFixed(2) : String(v ?? "N/D"));
const pct  = v => (Number.isFinite(num(v)) ? `${num(v).toFixed(2)}%` : "N/D%");

const toLocal = iso => {
  if (!iso) return "N/D";
  const offMs = Number(P.tz_offset_hours || 0) * 3600 * 1000;
  return new Date(new Date(iso).getTime() + offMs)
    .toISOString().replace("T"," ").substring(0,19);
};

const fmtDuration = m => {
  if (!Number.isFinite(num(m))) return "N/D";
  const mm = Math.max(0, Math.floor(num(m)));
  const h  = Math.floor(mm / 60);
  const r  = mm % 60;
  return h > 0 ? `${h}h ${r}m` : `${r}m`;
};

const title = `RECUPERACIÓN – Disco • ${j.instance_name} • ${j.unidad}`;

const facts = [
  { name: "Instancia", value: j.instance_name },
  { name: "Unidad",    value: j.unidad },
  { name: "Usado %",   value: pct(j.usado_pct) },
  { name: "Umbral",    value: `${j.threshold}%` },
  ...(j.alarm_started_at ? [{ name: "Alarma desde (local)", value: toLocal(j.alarm_started_at) }] : []),
  ...(j.alarm_duration_min != null ? [{ name: "Duración de la alarma", value: fmtDuration(j.alarm_duration_min) }] : []),
  { name: "Hora local", value: toLocal(new Date().toISOString()) }
];

const actions = [];
if (P.emit_kibana_button && P.kibana_url) {
  actions.push({
    "@type": "OpenUri",
    "name": P.kibana_cta_text || "Abrir tablero (24h)",
    "targets": [{ os: "default", uri: P.kibana_url }]
  });
}

// ✅ En modo "Run Once for Each Item" debemos devolver UN SOLO item (no array)
return {
  json: {
    "@type": "MessageCard",
    "@context": "https://schema.org/extensions",
    themeColor: "2EB886",
    summary: title,
    title,
    sections: [
      { markdown: true, text: "🟢 **RECUPERADO – Espacio en disco bajo el umbral**" },
      { markdown: true, facts }
    ],
    potentialAction: actions
  }
};

// === Function – Build extras (storage) — multi-unidad, alineado + Filtro estricto por unidad ===

// helpers
const fmt = n => Number.isFinite(Number(n)) ? Number(n).toFixed(2) : '-';
const getItems = (name, idx = undefined) => {
  try {
    if (idx === undefined) return $items(name).map(i => i.json);     // todos los items del nodo
    return ($items(name, 0, idx) || []).map(i => i.json);             // solo los del índice de entrada
  } catch { return []; }
};
const pathOf = r => String(r.path || r.physical_name || r.filename || '').toUpperCase();
const inDrive = (r, drive) => {
  if (!drive) return false;
  const p = pathOf(r);
  return p.startsWith(`${drive}:\\`);
};

// 1) ***CLAVE***: tomar SOLO las unidades que pasaron por If – Alarma
const baseItems = ($items('If – Alarma') || []).map(i => i.json);
if (!baseItems.length) return [];

// caches “ALL” para fallbacks
const ALL_files = getItems('MSSQL – Top DB files (unidad)');     // todos los archivos
const ALL_grow  = getItems('MSSQL – Autogrowth 24h (unidad)');   // global
const ALL_topdb = getItems('MSSQL – Top DB por base (unidad)');  // global

const out = [];

for (let idx = 0; idx < baseItems.length; idx++) {
  const base = baseItems[idx] || {};
  const N = Number(base.top_n ?? $json.top_n ?? 10);
  const drive = String(base.unidad || '').trim().charAt(0).toUpperCase(); // 'C' | 'E' | 'S'

  // 2) Files por índice, luego SIEMPRE filtrar por unidad; si queda vacío, fallback a ALL_* filtrado
  let filesIdx = getItems('MSSQL – Top DB files (unidad)', idx);
  let files = (filesIdx.length ? filesIdx : ALL_files).filter(r => inDrive(r, drive));

  // 3) Autogrowth (global, no depende de unidad) – usa por índice si existe, sino ALL
  let grow = getItems('MSSQL – Autogrowth 24h (unidad)', idx);
  if (!grow.length && ALL_grow.length) grow = ALL_grow;

  // 4) Top DB por base (GLOBAL). Si por índice vacío, usa ALL
  let topDbGlobalR = getItems('MSSQL – Top DB por base (unidad)', idx);
  if (!topDbGlobalR.length && ALL_topdb.length) topDbGlobalR = ALL_topdb;

  // ---------- Top archivos (por unidad estricta) ----------
  const seenFiles = new Set();
  const linesFiles = [];
  for (const r of files) {
    const key = `${r.db || '-'}|${pathOf(r)}`;
    if (seenFiles.has(key)) continue;
    seenFiles.add(key);
    linesFiles.push(
      `• ${r.db || '-'} • ${r.type || '-'} • ${fmt((Number(r.size_mb)||0)/1024)} GB • ${r.path || r.physical_name || '-'}`
    );
  }
  const linesFilesCut = linesFiles.slice(0, N);

  // ---------- Top bases GLOBAL (con fallback por unidad si global vacío) ----------
  const seen = new Set();
  const topDbGlobal = [];
  for (const r of topDbGlobalR) {
    const key = `${r.db || ''}|${Number(r.size_mb || 0).toFixed(2)}|${r.path||''}`;
    if (!seen.has(key)) { seen.add(key); topDbGlobal.push(r); }
  }
  topDbGlobal.sort((a,b) => Number(b.size_mb||0) - Number(a.size_mb||0));
  const topDbCut = topDbGlobal.slice(0, N);

  let linesByDb = topDbCut.map(r =>
    `• ${r.db || '-'} • ${fmt((Number(r.size_mb)||0)/1024)} GB • ${r.path || '-'}`
  );

  // si el global viniera vacío, calculamos por unidad con los archivos filtrados a esta unidad
  if (!linesByDb.length) {
    const sizeByDb = {};
    for (const r of files) {
      const db = r.db || 'desconocida';
      sizeByDb[db] = (sizeByDb[db] || 0) + Number(r.size_mb || 0);
    }
    linesByDb = Object.entries(sizeByDb)
      .sort((a,b) => b[1] - a[1])
      .slice(0, N)
      .map(([db, size_mb]) => `• ${db} • ${fmt(size_mb/1024)} GB`);
  }

  // ---------- Autogrowth (MB, dedupe + orden desc) ----------
  const growNorm = grow.map(r => ({
    tsRaw:  r.StartTime || r.starttime || '',
    tsTxt:  (r.StartTime || r.starttime || '').toString().replace('T',' ').replace('Z',''),
    db:     r.DatabaseName || r.DBName || r.dbname || '-',
    file:   r.FileName || r.filename || '-',
    mb:     Number(r.GrowthMB)
  }));
  const seenGrow = new Set();
  const growDedup = [];
  for (const g of growNorm) {
    const key = `${g.tsRaw}|${g.db}|${g.file}|${g.mb}`;
    if (seenGrow.has(key)) continue;
    seenGrow.add(key);
    growDedup.push(g);
  }
  growDedup.sort((a,b) => new Date(b.tsRaw) - new Date(a.tsRaw));
  const linesGrow = growDedup.slice(0, N).map(g =>
    `• ${g.tsTxt} • ${g.db} • +${fmt(g.mb)} MB • ${g.file}`
  );

  // ---------- Emitimos UN item por unidad ----------
  out.push({
    json: {
      ...base,
      extras_storage: {
        titles: {
          files: `📦 Archivos de base de datos (detalle por archivo en la unidad ${base.unidad || 'actual'})`,
          topdb: "🧩 Bases con mayor tamaño total (suma de archivos, todas las unidades)",
          grow:  "⚙️ Autogrowth en 24 h (crecimientos detectados, MB)"
        },
        top_files: linesFilesCut,
        top_db:    linesByDb,
        autogrow:  linesGrow
      }
    }
  });
}

return out;

// === Function – Build insert (tops) v2 (usa datos estructurados) ===

// helpers
function pick(name){ try { return $items(name).map(i => i.json); } catch { return []; } }
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random()*16|0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const N = Number($json.top_n ?? 10);

const base     = $json || {};
const instName = base.instance_name || base.instancia || '-';
const ts       = base.ts_utc || new Date().toISOString();
const run_id   = base.run_id || uuidv4();

// Datos estructurados de los nodos SQL
const topDbGlobalR = pick('MSSQL – Top DB por base (unidad)'); // [{db, size_mb, path}]
const filesR       = pick('MSSQL – Top DB files (unidad)');    // [{db, type, size_mb, path}]

const out = [];

// ---------- Top DB (global) ----------
const seenDb = new Set();
const dbList = [];
for (const r of topDbGlobalR) {
  const db   = r.db || '-';
  const size = Number(r.size_mb || 0);
  const key  = `${db}|${size.toFixed(2)}|${r.path||''}`;
  if (seenDb.has(key)) continue;
  seenDb.add(key);
  dbList.push({ db, size_mb: size, path: r.path || null });
}
// ordenar por tamaño desc y limitar
dbList.sort((a,b)=> b.size_mb - a.size_mb);
dbList.slice(0, N).forEach((r, i) => {
  out.push({
    json: {
      ts_utc: ts,
      run_id,
      instance_name: instName,
      scope_type: 'db',
      scope_key: r.db,
      rank_n: i+1,
      metric_name: 'size_gb',
      metric_value: Number((r.size_mb/1024).toFixed(2)),
      extra_json: JSON.stringify({
        fuente: 'top_db_global',
        path: r.path
      })
    }
  });
});

// ---------- Top files (por unidad) ----------
const seenFile = new Set();
const fileList = [];
for (const r of filesR) {
  const path = r.path || '-';
  if (seenFile.has(path)) continue;
  seenFile.add(path);
  fileList.push({
    db: r.db || '-',
    type: r.type || '-',
    size_mb: Number(r.size_mb || 0),
    path
  });
}
fileList.sort((a,b)=> b.size_mb - a.size_mb);
fileList.slice(0, N).forEach((r, i) => {
  out.push({
    json: {
      ts_utc: ts,
      run_id,
      instance_name: instName,
      scope_type: 'file',
      scope_key: r.path,
      rank_n: i+1,
      metric_name: 'size_gb',
      metric_value: Number((r.size_mb/1024).toFixed(2)),
      extra_json: JSON.stringify({
        fuente: 'top_files',
        db: r.db,
        type: r.type,
        unidad: base.unidad || null
      })
    }
  });
});

return out;

