-- ==== Resolver instancia (sin environment/region) ====
DECLARE @inst sysname = N'{{$json.instance_name}}';
IF (@inst IS NULL OR @inst = N'') SET @inst = N'{{$json.instancia}}';
IF (@inst IS NULL OR @inst = N'') SET @inst = N'-';

DECLARE @id int = (
  SELECT TOP (1) instance_id
  FROM OpsObservability.dbo.monitoring_instance WITH (NOLOCK)
  WHERE instance_name = @inst
);
IF @id IS NULL
BEGIN
  INSERT INTO OpsObservability.dbo.monitoring_instance (instance_name)
  VALUES (@inst);
  SET @id = SCOPE_IDENTITY();
END;

-- ==== Variables del ítem ====
DECLARE @ts_raw           nvarchar(64)  = N'{{$json.ts_utc}}';
DECLARE @scope_type       varchar(20)   = LTRIM(RTRIM('{{$json.scope_type}}'));
DECLARE @scope_key        nvarchar(260) = LTRIM(RTRIM(N'{{$json.scope_key}}'));
DECLARE @rank_n_txt       nvarchar(50)  = LTRIM(RTRIM(N'{{$json.rank_n}}'));
DECLARE @metric_name      varchar(50)   = LTRIM(RTRIM('{{$json.metric_name}}'));
DECLARE @metric_value_txt nvarchar(50)  = LTRIM(RTRIM(N'{{$json.metric_value}}'));
DECLARE @extra_json       nvarchar(max) = N'{{$json.extra_json}}';
DECLARE @run_id_txt       nvarchar(50)  = LTRIM(RTRIM(N'{{$json.run_id}}'));

-- ==== Fecha: ISO -> datetime, o GETUTCDATE() si viene vacía/mal ====
DECLARE @ts_clean nvarchar(64);
SET @ts_clean = REPLACE(REPLACE(ISNULL(@ts_raw,N''),'T',' '),'Z','');

DECLARE @ts_utc datetime;
IF (@ts_clean = N'' OR @ts_clean LIKE N'%undefined%' OR ISDATE(@ts_clean) <> 1)
  SET @ts_utc = GETUTCDATE();
ELSE
  SET @ts_utc = CAST(@ts_clean AS datetime);

-- ==== rank_n seguro ====
DECLARE @rank_n int;
IF (@rank_n_txt IS NULL OR @rank_n_txt = N'' OR @rank_n_txt LIKE N'%undefined%' OR ISNUMERIC(@rank_n_txt) <> 1)
  SET @rank_n = 0;
ELSE
  SET @rank_n = CAST(@rank_n_txt AS int);

-- ==== metric_value seguro (decimal o NULL) ====
DECLARE @metric_value decimal(18,2);
IF (@metric_value_txt IS NULL OR @metric_value_txt = N'' OR @metric_value_txt LIKE N'%undefined%')
  SET @metric_value = NULL;
ELSE
BEGIN
  DECLARE @metric_txt_norm nvarchar(50) = REPLACE(@metric_value_txt, ',', '.');
  SET @metric_value = CASE WHEN ISNUMERIC(@metric_txt_norm)=1 THEN CAST(@metric_txt_norm AS decimal(18,2)) ELSE NULL END;
END

-- ==== run_id: si falta o es inválido -> NEWID() ====
DECLARE @run_id uniqueidentifier;
IF (@run_id_txt IS NULL OR @run_id_txt = N'' OR @run_id_txt LIKE N'%undefined%')
  SET @run_id = NEWID();
ELSE
BEGIN
  BEGIN TRY
    SET @run_id = CONVERT(uniqueidentifier, @run_id_txt);
  END TRY
  BEGIN CATCH
    SET @run_id = NEWID();
  END CATCH
END

-- ==== Guard rails: bloquear vacíos/undefined ====
IF (@scope_type IS NULL OR @scope_type = '' OR @scope_type = 'undefined'
 OR @scope_key  IS NULL OR @scope_key  = '' OR @scope_key  = 'undefined'
 OR @metric_name IS NULL OR @metric_name = '' OR @metric_name = 'undefined')
  RETURN;

-- ==== INSERT final ====
INSERT INTO OpsObservability.dbo.monitoring_top_storage
  (ts_utc, instance_id, scope_type, scope_key, rank_n,
   metric_name, metric_value, extra_json, run_id)
VALUES
  (@ts_utc, @id, @scope_type, @scope_key, @rank_n,
   @metric_name, @metric_value, @extra_json, @run_id);

