// === Function – RECOVERY (solo una vez por transición) ===
const items = $input.all();

return items.map(it => {
  const j  = it.json;

  const st = String(j.state || '').toUpperCase().trim();      // 'ALARM' | 'NORMAL'
  const tr = String(j.transition || '').toUpperCase().trim(); // 'RAISE' | 'RECOVER' | 'HOLD' | 'NONE'
  const justChanged = (j.last_change === j.ts_utc);            // <- lo conservamos por compat, pero ya no lo usamos

  // Antes: (st==='NORMAL') && (tr==='RECOVER' || justChanged)
  // Ahora: SOLO cuando hay transición real a RECOVER
  const send_recovery = (st === 'NORMAL' && tr === 'RECOVER');

  return { json: { ...j, send_recovery } };
});

