SET NOCOUNT ON;
DECLARE @now_utc DATETIME = GETUTCDATE();

DECLARE @inst sysname = N'{{$json.instance_name}}';
DECLARE @unidad nvarchar(50) = N'{{$json.unidad}}';
DECLARE @state nvarchar(10)  = N'{{$json.state}}';

DECLARE @instance_id int;
SELECT TOP 1 @instance_id = instance_id
FROM OpsObservability.dbo.monitoring_instance WITH (NOLOCK)
WHERE instance_name=@inst;

IF @instance_id IS NULL
BEGIN
  -- por si acaso aún no existe:
  INSERT INTO OpsObservability.dbo.monitoring_instance(instance_name, environment, region)
  VALUES(@inst, 'prod', 'eastus2');
  SELECT TOP 1 @instance_id = instance_id
  FROM OpsObservability.dbo.monitoring_instance WITH (NOLOCK)
  WHERE instance_name=@inst;
END

MERGE OpsObservability.dbo.monitoring_disk_state AS T
USING (SELECT @instance_id AS instance_id, @unidad AS unidad) AS S
ON (T.instance_id = S.instance_id AND T.unidad = S.unidad)
WHEN MATCHED THEN
  UPDATE SET last_state=@state, last_change_utc=@now_utc
WHEN NOT MATCHED THEN
  INSERT(instance_id, unidad, last_state, last_change_utc)
  VALUES(@instance_id, @unidad, @state, @now_utc);
